import React, { useEffect, useState } from 'react';
import './Carrito.css'
import NavMenu from '../../navMenu/NavMenu';
import Loading from '../../loading/Loading';
const Carrito = ()=>{
    const [loading, setLoading] = useState(true);

    useEffect(() => {
      const timer = setTimeout(() => {
        setLoading(false);
      }, 3000);
  
      return () => clearTimeout(timer);
    }, []);
    return (
        <div>
            {loading && <Loading />}
            <NavMenu className="nav-menu" />
            <div className="CarritoBody">
                <div className="Carrito-cards">
                    <div className="Carrito-cards-titulo">
                        <h1>Carrito de Compras</h1>
                    </div>
                    <div className="Carrito-cards-contenido">
                        <div className='item-card'>
                            <div className='item-card-imagen'>
                                {/* Imagen del producto */}
                                <img src="url-de-la-imagen" alt="Producto" />
                            </div>
                            <div className='item-card-caracteristicas'>
                                {/* Características del producto */}
                                <p>Nombre del producto</p>
                                <p>Descripción breve</p>
                            </div>
                            <div className='item-card-controles'>
                                <div className='control-eliminar'>
                                    {/* Botón de eliminar */}
                                    <button>Eliminar</button>
                                </div>
                                <div className='control-cantidad'>
                                    {/* Controles de cantidad */}
                                    <button>-</button>
                                    <input type="text" value="1" readOnly />
                                    <button>+</button>
                                </div>
                            </div>
                            <div className='item-card-costo'>
                                {/* Costo del producto */}
                                <p>$XX.XX</p>
                            </div>
                        </div>
                    </div>
                    <div className='Carrito-pagar'>
                        <button>Pagar</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Carrito
